#[derive(Clone, Copy, Debug)]
pub enum NativeFamily { PositionAbs, Velocity }
#[derive(Clone, Copy, Debug)]
pub enum NativeGraphKind { World, Model, Link, Joint }
#[derive(Clone, Copy, Debug)]
pub enum NativeKind { Config, Registry, RoundInput, Pre, RoundEnd, Publication, Tap, Fence, Summary }
#[derive(Clone, Copy, Debug)]
pub enum NativeRoundRole { Initial, Baseline, Probe, Measurement }
#[derive(Clone, Copy, Debug)]
pub enum NativeRegistryStage { Empty, AfterPosition0, AfterPosition2 }
#[derive(Clone, Copy, Debug)]
pub enum NativeInterface { Configure, ConfigureParameters, PreUpdate }
#[derive(Clone, Copy, Debug)]
pub enum NativeParameterResultType { Success, AlreadyDeclared, InvalidType, NotDeclared, ClientTimeout, Unexpected }
#[derive(Clone, Copy, Debug)]
pub enum NativeCompletion { ObservedOriginalPreUpdateComponentEffect }
#[derive(Clone, Copy, Debug)]
pub enum NativeFenceScope { TapIsNotPrivateCallbackAck }
#[derive(Clone, Copy, Debug)]
pub enum NativeSettings { Position(NativePositionSettings), Velocity(NativeVelocitySettings) }
#[derive(Clone, Copy, Debug)]
pub struct NativeStamp { pub sec: i64, pub nsec: i32 }
#[derive(Clone, Copy, Debug)]
