pub struct NativePositionSettings { pub joint_index: u32, pub use_velocity_commands: bool, pub cmd_max_bits: u64, pub initial_target_bits: u64 }
#[derive(Clone, Copy, Debug)]
pub struct NativeVelocitySettings { pub use_force_commands: bool, pub initial_target_bits: u64 }
#[derive(Clone, Copy, Debug)]
pub struct NativeDiscovery { pub publisher_type_names: &'static [&'static str], pub subscriber_type_names: &'static [&'static str], pub has_connections: bool }
#[derive(Clone, Copy, Debug)]
pub struct NativeConfiguration { pub ordinal: u64, pub slot: u32, pub owner: u32, pub model_entity: u64, pub joint_entity: u64, pub model_name: &'static str, pub joint_name: &'static str, pub topic: &'static str, pub plugin_xml: &'static str, pub settings: NativeSettings, pub graph: &'static [NativeGraphNode], pub parameter_prefix_from_public_joint_scope: Option<&'static str>, pub configure_index: u32, pub interfaces: &'static [NativeInterface], pub discovery: NativeDiscovery }
