#[derive(Clone, Copy, Debug)]
pub struct NativeInfo { pub sim_time_ns: u64, pub real_time_ns: u64, pub dt_ns: i64, pub iterations: u64, pub paused: bool }
#[derive(Clone, Copy, Debug)]
pub struct NativeInput { pub slot: u32, pub model_entity: u64, pub joint_entity: u64, pub joint_position: Option<&'static [u64]>, pub joint_velocity: Option<&'static [u64]> }
