#[derive(Clone, Copy, Debug)]
pub struct NativeRoundInput { pub ordinal: u64, pub round_index: u64, pub phase: Option<u32>, pub role: NativeRoundRole, pub probe_index: Option<u32>, pub measurement_index: Option<u32>, pub info: NativeInfo, pub inputs: &'static [NativeInput; 4], pub commands_before: &'static [NativeCommandState; 4], pub registry_before: Option<&'static [NativeParameterValue; 16]> }
#[derive(Clone, Copy, Debug)]
pub struct NativePreCall { pub ordinal: u64, pub round_index: u64, pub call_index: u64, pub slot: u32, pub info: NativeInfo, pub inputs_after: &'static [NativeInput; 4], pub commands_after: &'static [NativeCommandState; 4], pub registry_after: Option<&'static [NativeParameterValue; 16]>, pub selected_index: u32 }
