pub struct NativePublication { pub ordinal: u64, pub phase: u32, pub slot: u32, pub topic: &'static str, pub message: &'static NativeDouble, pub publish_returned_true: bool }
#[derive(Clone, Copy, Debug)]
pub struct NativeTap { pub ordinal: u64, pub phase: u32, pub slot: u32, pub topic: &'static str, pub arrival_ordinal: u64, pub arrival_elapsed_ns: u64, pub message: &'static NativeDouble }
#[derive(Clone, Copy, Debug)]
pub struct NativeFence { pub ordinal: u64, pub phase: u32, pub slot: u32, pub publication_ordinal: u64, pub tap_ordinal: u64, pub baseline_round_index: u64, pub probe_round_indices: &'static [u64], pub matched_probe_round_index: u64, pub completion: NativeCompletion, pub evidence_scope: NativeFenceScope }
#[derive(Clone, Copy, Debug)]
pub struct NativeCounts { pub configurations: u64, pub registry_records: u64, pub round_inputs: u64, pub pre_update_calls: u64, pub round_ends: u64, pub publications: u64, pub tap_records: u64, pub fences: u64, pub command_state_getbacks: u64, pub helper_registry_get_calls: u64, pub raw_rows: u64 }
#[derive(Clone, Copy, Debug)]
pub struct NativeSummary { pub ordinal: u64, pub state: &'static str, pub probe_round_counts: &'static [u32; 4], pub counts: NativeCounts }
#[derive(Clone, Copy, Debug)]
pub struct NativeRowRef { pub kind: NativeKind, pub index: usize, pub raw_ordinal: u64 }
#[derive(Clone, Copy, Debug)]
pub struct NativeCase { pub schema: &'static str, pub family: NativeFamily, pub selected_slots: &'static [u32; 2], pub configurations: &'static [NativeConfiguration], pub registry_records: &'static [NativeRegistryRecord], pub round_inputs: &'static [NativeRoundInput], pub pre_calls: &'static [NativePreCall], pub round_ends: &'static [NativeRoundEnd], pub publications: &'static [NativePublication], pub taps: &'static [NativeTap], pub fences: &'static [NativeFence], pub summary: &'static NativeSummary, pub raw_order: &'static [NativeRowRef] }
